### 8.1 JSON Serialization Standards

```python
import json
from datetime import datetime
from typing import Any, Dict
from decimal import Decimal

class QueueMessageEncoder(json.JSONEncoder):
    """Custom JSON encoder for queue messages"""

    def default(self, obj: Any) -> Any:
        if isinstance(obj, datetime):
            return obj.isoformat()
        elif isinstance(obj, Decimal):
            return float(obj)
        elif hasattr(obj, 'to_dict'):
            return obj.to_dict()
        return super().default(obj)

def serialize_payload(payload: Dict[str, Any]) -> str:
    """Serialize message payload to JSON string"""
    return json.dumps(payload, cls=QueueMessageEncoder, ensure_ascii=False)

def deserialize_payload(payload_str: str) -> Dict[str, Any]:
    """Deserialize message payload from JSON string"""
    return json.loads(payload_str)
```

