### 8.2 Message Compression

For large messages (>1KB), use compression:

```python
import gzip
import base64

def compress_payload(payload: str) -> str:
    """Compress large message payloads"""
    if len(payload) > 1024:  # 1KB threshold
        compressed = gzip.compress(payload.encode('utf-8'))
        return base64.b64encode(compressed).decode('ascii')
    return payload

def decompress_payload(payload: str) -> str:
    """Decompress message payloads"""
    try:
        compressed_data = base64.b64decode(payload.encode('ascii'))
        return gzip.decompress(compressed_data).decode('utf-8')
    except Exception:
        return payload  # Not compressed
```

