### 12.1 Message Encryption

```python
from cryptography.fernet import Fernet

class MessageEncryption:
    """Encrypt sensitive message content"""

    def __init__(self, encryption_key: bytes):
        self.cipher = Fernet(encryption_key)

    def encrypt_payload(self, payload: str) -> str:
        """Encrypt message payload"""
        encrypted = self.cipher.encrypt(payload.encode('utf-8'))
        return base64.b64encode(encrypted).decode('ascii')

    def decrypt_payload(self, encrypted_payload: str) -> str:
        """Decrypt message payload"""
        encrypted_data = base64.b64decode(encrypted_payload.encode('ascii'))
        decrypted = self.cipher.decrypt(encrypted_data)
        return decrypted.decode('utf-8')
```
